$_MODULE['<{emporiqa}prestashop>configure_c5beaa750a2312640e423be94b71e796'] = 'in Emporiqa angezeigt als';
$_MODULE['<{emporiqa}prestashop>configure_bfb91a9dee36eb6a087ec089b5d12096'] = 'Die Regel Bestellstatus ist aktiv, daher wird die alte Bestellverfolgung unter Erweitert nicht mehr benötigt. Entfernen Sie zuerst ihre Adresse in Ihrem Emporiqa-Dashboard (Settings > Integration > For your developer > Order tracking API URL), stellen Sie sie dann auf Nein und klicken Sie auf Speichern.';
$_MODULE['<{emporiqa}prestashop>configure_19b8ee5afc059faabeebd06021a124b7'] = 'Adresse für den Bestellstatus';
$_MODULE['<{emporiqa}prestashop>configure_541397979e2ebcc81ef825b6031ac61e'] = 'Emporiqa trägt sie für Sie ein, wenn Sie die Regel Bestellstatus hinzufügen. Falls Sie doch einmal nach der Adresse gefragt werden, verwenden Sie diese.';
$_MODULE['<{emporiqa}prestashop>configure_521c36a31c2762741cf0f8890cbe05e3'] = 'Aktiv';
$_MODULE['<{emporiqa}prestashop>configure_f3c7d07fc249fd908dfc4347aa429508'] = 'Nicht hinzugefügt';
$_MODULE['<{emporiqa}prestashop>configure_c826b611ca0ee47b57eb420b30c893e5'] = 'Aktiv und Nicht hinzugefügt zeigen, was Emporiqa bei Ihrer letzten Verbindung oder beim letzten Verbindungstest (Tab Synchronisation) gemeldet hat. Führen Sie nach einer Regeländerung „Verbindung testen“ aus, um sie zu aktualisieren.';
$_MODULE['<{emporiqa}prestashop>configure_9ca9cdda276ecb80fbc19cc7aae143dc'] = 'Regeln sagen dem Chat, was zu tun ist, wenn ein Kunde nach etwas Bestimmtem fragt. Die Regel unten liest Ihre PrestaShop-Bestellungen über dieses Modul. Klicken Sie auf „In Emporiqa öffnen“, um sie zu testen und dort zu aktivieren. Regeln, die Ihren Shop nicht brauchen, etwa Rücksendeanfragen, fügen Sie in Emporiqa unter Settings > Rules hinzu.';
$_MODULE['<{emporiqa}prestashop>configure_95111924eb01abc57a4c48041d3a83e1'] = 'Beantwortet „Wo ist meine Bestellung?“ aus Ihren PrestaShop-Bestellungen. Ein in Ihrem Shop angemeldeter Kunde nennt nur die Bestellnummer; ein Gast nennt zusätzlich die E-Mail-Adresse der Bestellung.';
$_MODULE['<{emporiqa}prestashop>order_tracking_field_d5ea57f5abb0c7c0e6a596e02f33b478'] = 'Alte Bestellverfolgung (veraltet)';
